import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  cardClasses,
  cardActionClasses,
  cardContentClasses,
  cardDescriptionClasses,
  cardFooterClasses,
  cardHeaderClasses,
  cardTitleClasses,
} from "./view";

export {
  cardActionClasses,
  cardClasses,
  cardContentClasses,
  cardDescriptionClasses,
  cardFooterClasses,
  cardHeaderClasses,
  cardTitleClasses,
} from "./view";

const cn = (base: string, classes?: string): string =>
  [base, classes]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const view = <ParentMessage>(
  children: readonly Html[],
  classes?: string,
  size: "Default" | "Small" = "Default"
): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "card"),
      h.DataAttribute("size", size === "Small" ? "sm" : "default"),
      h.Class(cn(cardClasses, classes)),
    ],
    children
  );
};

export const headerView = <ParentMessage>(
  children: readonly Html[],
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "card-header"),
      h.Class(cn(cardHeaderClasses, classes)),
    ],
    children
  );
};

export const titleView = <ParentMessage>(
  label: string,
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.h3(
    [
      h.DataAttribute("slot", "card-title"),
      h.Class(cn(cardTitleClasses, classes)),
    ],
    [label]
  );
};

export const descriptionView = <ParentMessage>(
  label: string,
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.p(
    [
      h.DataAttribute("slot", "card-description"),
      h.Class(cn(cardDescriptionClasses, classes)),
    ],
    [label]
  );
};

export const actionView = <ParentMessage>(
  children: readonly Html[],
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "card-action"),
      h.Class(cn(cardActionClasses, classes)),
    ],
    children
  );
};

export const contentView = <ParentMessage>(
  children: readonly Html[],
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "card-content"),
      h.Class(cn(cardContentClasses, classes)),
    ],
    children
  );
};

export const footerView = <ParentMessage>(
  children: readonly Html[],
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "card-footer"),
      h.Class(cn(cardFooterClasses, classes)),
    ],
    children
  );
};

export const cardClasses =
  "group/card flex flex-col gap-(--card-spacing) overflow-hidden rounded-xl border border-gray-200 bg-white py-(--card-spacing) text-sm text-gray-950 shadow [--card-spacing:--spacing(4)] data-[size=sm]:[--card-spacing:--spacing(3)] has-data-[slot=card-footer]:pb-0 has-[>img:first-child]:pt-0";

export const cardHeaderClasses =
  "group/card-header grid auto-rows-min items-start gap-1 rounded-t-xl px-(--card-spacing) has-data-[slot=card-action]:grid-cols-[1fr_auto] has-data-[slot=card-description]:grid-rows-[auto_auto] [.border-b]:pb-(--card-spacing)";

export const cardTitleClasses =
  "text-lg font-semibold leading-none tracking-normal text-gray-950";

export const cardDescriptionClasses = "text-sm text-gray-600";

export const cardActionClasses =
  "col-start-2 row-span-2 row-start-1 self-start justify-self-end";

export const cardContentClasses = "px-(--card-spacing)";

export const cardFooterClasses =
  "flex items-center rounded-b-xl border-t border-gray-200 bg-gray-50 p-(--card-spacing)";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Card from "./index";

const view = (): Html => {
  const h = html<never>();

  return Card.view([
    Card.headerView([
      Card.titleView("Project health"),
      Card.descriptionView(
        "Current registry progress and verification status."
      ),
    ]),
    Card.contentView([h.p([], ["Ready"])]),
    Card.footerView([h.span([], ["Public"])]),
  ]);
};

describe("Card registry view", () => {
  test("renders the documented static surface", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Project health")).toExist(),
      Scene.expect(
        Scene.text("Current registry progress and verification status.")
      ).toExist()
    );
  });
});
